    var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  background: var(--focus);
  color: #000;
  padding: 0.6rem 1rem;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--text);
}

.container {
  width: min(760px, 92%);
  margin: 0 auto;
}

main:focus { outline: none; }

.page-header {
  padding: 4rem 0 2.5rem;
  border-bottom: 1px solid var(--border);
}

.eyebrow {
  margin: 0 0 0.5rem;
  color: var(--accent);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.85rem;
}

.page-header h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(2rem, 4vw, 3rem);
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.lede {
  margin: 0;
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 56ch;
}

main {
  padding: 2.5rem 0 4rem;
}

main h2 {
  margin: 0 0 0.5rem;
  font-size: 1.5rem;
}

.section-intro {
  color: var(--text-muted);
  margin: 0 0 1.5rem;
}

.faq-controls {
  display: flex;
  gap: 0.6rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.btn {
  background: var(--bg-elevated);
  color: var(--text);
  border: 1px solid var(--border-strong);
  padding: 0.55rem 1rem;
  border-radius: 8px;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}
.btn:hover { background: var(--bg-hover); border-color: var(--accent); }
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.example {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.example:hover { border-color: var(--border-strong); }
.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--accent);
  box-shadow: var(--shadow);
}

.example h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
}

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.25rem;
  background: transparent;
  border: 0;
  color: var(--text);
  font: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius);
}
.faq-trigger:hover { background: var(--bg-hover); }
.faq-trigger:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-question {
  flex: 1;
}

.faq-icon {
  flex: 0 0 auto;
  width: 1.25rem;
  height: 1.25rem;
  position: relative;
  transition: transform 0.2s ease;
}
.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  background: var(--accent-strong);
  border-radius: 2px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.faq-icon::before { width: 100%; height: 2px; }
.faq-icon::after  { width: 2px; height: 100%; transition: transform 0.2s ease; }

.faq-trigger[aria-expanded="true"] .faq-icon::after {
  transform: translate(-50%, -50%) scaleY(0);
}

.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--text);
  border-top: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.015);
}
.details[hidden] { display: none; }
.details p:first-child { margin-top: 1rem; }
.details p:last-child  { margin-bottom: 0; }
.details ul {
  margin: 0.6rem 0;
  padding-left: 1.4rem;
}
.details li { margin: 0.25rem 0; }

.page-footer {
  border-top: 1px solid var(--border);
  padding: 1.5rem 0;
  color: var(--text-muted);
  text-align: center;
  font-size: 0.9rem;
}

@media (max-width: 480px) {
  .page-header { padding: 2.5rem 0 1.5rem; }
  .faq-trigger { padding: 1rem; font-size: 1rem; }
  .details { padding: 0 1rem 1rem; }
}
