  function setExpanded(trigger, expanded) {
    const panelId = trigger.getAttribute('aria-controls');
    const panel = document.getElementById(panelId);
    if (!panel) return;
    trigger.setAttribute('aria-expanded', String(expanded));
    if (expanded) {
      panel.removeAttribute('hidden');
    } else {
      panel.setAttribute('hidden', '');
    }
  }

  triggers.forEach((trigger, idx) => {
    trigger.addEventListener('click', () => {
      const expanded = trigger.getAttribute('aria-expanded') === 'true';
      setExpanded(trigger, !expanded);
    });

    trigger.addEventListener('keydown', (e) => {
      let target = null;
      switch (e.key) {
        case 'ArrowDown':
          target = triggers[(idx + 1) % triggers.length];
          break;
        case 'ArrowUp':
          target = triggers[(idx - 1 + triggers.length) % triggers.length];
          break;
        case 'Home':
          target = triggers[0];
          break;
        case 'End':
          target = triggers[triggers.length - 1];
          break;
      }
      if (target) {
        e.preventDefault();
        target.focus();
      }
    });
  });

  document.querySelectorAll('[data-action]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const expand = btn.dataset.action === 'expand-all';
      triggers.forEach((t) => setExpanded(t, expand));
    });
  });
})();

